connection = sqlite3.connect(DATABASE)
cursor = connection.cursor()

cursor.execute("""
CREATE TABLE IF NOT EXISTS questions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    question TEXT NOT NULL,
    option1 TEXT NOT NULL,
    option2 TEXT NOT NULL,
    option3 TEXT NOT NULL,
    option4 TEXT NOT NULL,
    correct_answer TEXT NOT NULL,
    hint TEXT,
    category TEXT DEFAULT 'Python'
)""")

cursor.execute("""
CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT NOT NULL,
    email TEXT,
    mobile TEXT,
    profile_picture TEXT,
    education TEXT,
    location TEXT
)""")

cursor.execute("""
CREATE TABLE IF NOT EXISTS leaderboard (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    player_name TEXT NOT NULL,
    score INTEGER NOT NULL,
    total_questions INTEGER NOT NULL,
    category TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
)""")

cursor.execute("""
CREATE TABLE IF NOT EXISTS progress (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER,
    category TEXT NOT NULL,
    score INTEGER DEFAULT 0,
    total_questions INTEGER DEFAULT 0,
    percentage REAL DEFAULT 0,
    completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
)""")

cursor.execute("""
CREATE TABLE IF NOT EXISTS learning_topics (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    category TEXT NOT NULL,
    level TEXT DEFAULT 'Beginner',
    icon TEXT DEFAULT '📚'
)""")

# Replace quiz questions so the database exactly matches this seed.
cursor.execute("DELETE FROM questions")
cursor.executemany("""
INSERT INTO questions
(question, option1, option2, option3, option4, correct_answer, hint, category)
VALUES (?, ?, ?, ?, ?, ?, ?, ?)
""", [(q[0], q[1], q[2], q[3], q[4], q[5], "Think about the core idea and how it is used.", q[6]) for q in questions])

# Rebuild the learning-topic list so Learn and Quiz stay in sync.
cursor.execute("DELETE FROM learning_topics")
cursor.executemany("""
INSERT INTO learning_topics (title, description, category, level, icon)
VALUES (?, ?, ?, ?, ?)
""", learning_topics)

# Keep the existing default user if one already exists.
cursor.execute("SELECT COUNT(*) FROM users")
if cursor.fetchone()[0] == 0:
    cursor.execute("""
    INSERT INTO users (username, email, mobile, profile_picture, education, location)
    VALUES (?, ?, ?, ?, ?, ?)
    """, ("Sri Devi", "sridevi@example.com", "+91 98765 43210", "default.png", "B.Sc. Computer Science", "Chennai, India"))

connection.commit()
connection.close()

